CREATE TABLE public.campaign_status_history ( id BIGSERIAL NOT NULL, campaign_id BIGINT NOT NULL, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, changed_by VARCHAR(100), changed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT,
CONSTRAINT pk_campaign_status_history PRIMARY KEY (id),
CONSTRAINT fk_status_history_campaign FOREIGN KEY (campaign_id) REFERENCES public.campaign(id) ON DELETE CASCADE );
CREATE INDEX idx_status_history_campaign ON public.campaign_status_history(campaign_id);
